package com.cropdeal.order;
import com.cropdeal.order.client.*; import com.cropdeal.order.dto.*; import com.cropdeal.order.entity.*; import com.cropdeal.order.repository.*; import com.cropdeal.order.service.*; import org.junit.jupiter.api.*; import org.mockito.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import java.util.*;
import static org.mockito.Mockito.*; import static org.mockito.ArgumentMatchers.*;
class NegotiationServiceTest {
 @Mock NegotiationRepository negotiations; @Mock OfferRepository offers; @Mock CropServiceClient crops; @Mock UserServiceClient users; @Mock EventSourcingService events;
 @BeforeEach void set(){MockitoAnnotations.openMocks(this);var a=new UsernamePasswordAuthenticationToken("dealer@test.com",null,List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_DEALER")));a.setDetails(200L);SecurityContextHolder.getContext().setAuthentication(a);}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void farmerAskingPriceIsStartingPoint(){NegotiationService s=new NegotiationService(negotiations,offers,crops,users,events);UserResponse d=new UserResponse();d.setId(20L);d.setAuthUserId(200L);d.setRole("DEALER");d.setActive(true);when(users.getByAuthUserId(200L)).thenReturn(d);CropResponse c=new CropResponse();c.setId(1L);c.setFarmerId(10L);c.setStatus("AVAILABLE");c.setQuantity(100.0);c.setExpectedPrice(4000.0);when(crops.getCrop(1L)).thenReturn(c);when(negotiations.save(any())).thenAnswer(inv->{Negotiation n=inv.getArgument(0);n.setId(7L);return n;});when(offers.findByNegotiationIdOrderByCreatedAtAsc(7L)).thenReturn(List.of());NegotiationRequest q=new NegotiationRequest();q.setCropId(1L);q.setDealerId(20L);q.setQuantity(10.0);q.setAmount(3700.0);NegotiationResponse r=s.start(q);Assertions.assertEquals(4000.0,r.getAskingPrice());Assertions.assertEquals(3700.0,r.getCurrentOffer());}
}
